<script setup>
import { assetUrl } from '../lib/assets.js'
import { computed,ref } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { ArrowLeft,Copy,MessageCircle,Info,ShieldCheck,FileCheck2,FileText } from 'lucide-vue-next'
import { ElMessage } from 'element-plus'
import PageTitle from '../components/PageTitle.vue'
import StatusBadge from '../components/StatusBadge.vue'
import FileUpload from '../components/FileUpload.vue'
import OrderAction from '../components/OrderAction.vue'
import { state,orderById,taskById,money,income,setOrderStatus,stamp,imageOf } from '../lib/store'
import { requireRole,notify,confirm } from '../lib/actions'
const route=useRoute(),router=useRouter(),order=computed(()=>orderById(route.params.id)),files=ref([]),note=ref(''),agreed=ref(false),busy=ref(false)
async function submit(){const o=order.value;if(busy.value||o.status!=='待交付'||!requireRole(router,'creator'))return;if(!files.value.length){ElMessage.warning('请至少添加 1 个作品文件');return}if(!agreed.value){ElMessage.warning('请勾选 AIGC 创作声明');return}if(!(await confirm('本次仅保存交付演示，未上传文件至服务器、未执行真实内容审核。确认后订单进入待验收。','提交作品')))return;busy.value=true;o.files=files.value.map(f=>({...f}));o.versions.push({version:o.version,note:note.value||'作品已提交，请查收。',result:'待验收',at:stamp(),files:o.files});setOrderStatus(o,'待验收');o.hours=72;notify('演示作品已提交，请前往商家端体验验收');busy.value=false}
async function copy(){try{await navigator.clipboard.writeText(order.value.id);notify('订单号已复制')}catch{ElMessage.info('请手动复制订单号：'+order.value.id)}}
function sample(){files.value=[1,2,3,4,5].map(i=>({uid:`delivery-${i}`,name:`主图_v${order.value.version}_${i}.jpg`,image:assetUrl(`pages/delivery-${i}.webp`),size:180000,type:'image'}));note.value='已根据反馈调整背景明度与产品光影，保留包装细节，统一了画面风格。';notify('已添加设计稿中的 5 张示例作品')}
</script>
<template><div v-if="order"><PageTitle title="订单详情" description="查看需求、跟进版本，完成每一次交付。"><el-button @click="router.push('/creator/orders')"><ArrowLeft/>返回我的订单</el-button></PageTitle><div class="order-detail-heading"><img :src="imageOf(order.art)" :alt="order.title"/><div><h2>{{order.title}}</h2><StatusBadge :status="order.status"/></div></div><div class="panel order-metrics"><div><label>订单号</label><strong>{{order.id}} <button @click="copy" aria-label="复制订单号"><Copy :size="14"/></button></strong></div><div><label>任务赏金</label><strong class="price-text">¥{{money(order.cents)}}</strong></div><div><label>预计实得</label><strong class="price-text">¥{{money(income(order.cents))}}</strong></div><div><label>{{order.status==='待验收'?'距自动验收':'距交付'}}</label><strong :class="{'price-text':order.hours<12}">{{['待交付','待验收'].includes(order.status)?`${order.hours} 小时`:'—'}}</strong></div></div><div class="columns wide-left"><div class="stack"><section class="panel"><h2>版本与进度</h2><el-timeline><el-timeline-item v-for="(v,i) in order.versions" :key="i" :timestamp="v.at" :type="v.result==='已驳回'?'danger':'primary'"><strong>v{{v.version}} · {{v.result}}</strong><p class="muted small">{{v.reason||v.note}}</p></el-timeline-item><el-timeline-item v-if="order.status==='待交付'" type="primary" hollow><strong>v{{order.version}} 待提交</strong><p class="muted small">当前版本 · 剩余修改 {{order.remainingRevisions}} 轮</p></el-timeline-item><el-timeline-item v-if="!order.versions.length" timestamp="示例订单"><strong>{{order.status==='待验收'?'v1 已提交，等待商家验收':'订单已创建'}}</strong></el-timeline-item></el-timeline><div class="divider"/><template v-if="order.status==='待交付'"><div class="panel-title"><h2>提交作品</h2><el-button link type="primary" @click="sample">使用示例作品</el-button></div><FileUpload v-model="files" label="添加作品"/><el-form label-position="top" style="margin-top:20px"><el-form-item label="修改说明（选填）"><el-input v-model="note" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="说明本次调整与交付内容，便于商家核对……"/></el-form-item></el-form><el-checkbox v-model="agreed">我承诺作品为 AI 辅助生成并经人工精修，无侵权内容，同意平台标识规范。</el-checkbox><div class="inline-actions" style="margin-top:20px"><el-button type="primary" :disabled="!agreed" :loading="busy" @click="submit">提交作品（演示）</el-button><span class="field-help">正式服务中，内容审核通过后进入商家验收。</span></div></template><template v-else><div class="info-note" :class="{success:order.status==='已完成'}"><FileCheck2/>{{order.status==='待验收'?'作品已提交，等待商家验收。演示不会自动推进时间。':order.status==='已完成'?'订单已完成，收益已按订单状态结算。':'订单处于纠纷处理阶段。'}}</div><div class="image-gallery" style="margin-top:18px"><div v-for="(f,i) in order.files.filter(f=>f.image)" :key="f.uid" class="gallery-item"><el-image :src="f.image" :preview-src-list="order.files.filter(f=>f.image).map(f=>f.image)" :initial-index="i" preview-teleported :alt="f.name"/><span v-if="!f.image.startsWith(assetUrl(''))" class="ai-corner">AI 生成</span></div></div><div v-if="order.files.some(f=>!f.image)" class="delivery-document-list"><div v-for="f in order.files.filter(f=>!f.image)" :key="f.uid"><FileText :size="17"/><span>{{f.name}}</span><small>交付文件</small></div></div><OrderAction v-if="order.status==='已完成'" :order="order" kind="review" style="margin-top:20px"/></template></section></div><aside class="panel"><h2>需求速览</h2><div class="data-lines"><div><label>任务类目</label><strong>{{order.category}}</strong></div><div><label>交付规范</label><strong>{{taskById(order.taskId)?.deliverables||'按任务详情要求交付'}}</strong></div><div><label>交付周期</label><strong>{{order.days}} 天</strong></div><div><label>免费修改次数</label><strong>{{order.revisions}} 轮</strong></div><div><label>剩余修改次数</label><strong class="price-text">{{order.remainingRevisions}} 轮</strong></div></div><div class="divider"/><h3>商家信息</h3><div class="person"><div class="avatar" style="background:#eaf0e3;color:#6e8c48">禾</div><div><h3>{{order.merchant}}</h3><p>美妆护肤品牌 · 示例</p></div></div><el-button class="full-button" style="margin-top:20px" @click="router.push('/messages?chat=merchant')"><MessageCircle/>联系商家</el-button><div class="divider"/><div class="inline-actions"><OrderAction v-if="order.status==='待交付'" :order="order" kind="extend" link/><OrderAction v-if="['待交付','待验收'].includes(order.status)" :order="order" kind="dispute" link/></div><p v-if="order.extension" class="field-help">延期申请：{{order.extension.status}} · {{order.extension.hours}} 小时</p><div class="info-note" style="margin-top:18px"><ShieldCheck/>平台内沟通、提交与验收，保障双方权益。</div></aside></div></div><el-empty v-else description="没有找到这份订单"><el-button @click="router.push('/creator/orders')">返回我的订单</el-button></el-empty></template>
<style scoped>.order-detail-heading{display:flex;align-items:center;gap:22px;margin-bottom:22px}.order-detail-heading>img{width:135px;height:95px;object-fit:cover;object-position:left;border-radius:7px}.order-detail-heading h2{margin-bottom:12px}.order-metrics{display:grid;grid-template-columns:1.4fr 1fr 1fr 1fr;margin-bottom:22px!important}.order-metrics>div{border-right:1px solid #dce2ec;padding:0 20px}.order-metrics>div:first-child{padding-left:0}.order-metrics>div:last-child{border:0}.order-metrics label{display:block;color:#788393;font-size:12px;margin-bottom:7px}.order-metrics strong{font-size:22px;font-weight:600}.order-metrics>div:first-child strong{font-size:12px;overflow-wrap:anywhere}.order-metrics button{vertical-align:middle;color:#8190a6}.el-timeline{padding-left:6px;margin:25px 0}.el-timeline p{margin:5px 0 0}@media(max-width:1200px){.order-metrics{grid-template-columns:repeat(2,1fr);gap:18px}.order-metrics>div:nth-child(3){padding-left:0}}@media(max-width:650px){.order-detail-heading>img{width:95px;height:85px}.order-detail-heading h2{font-size:17px}.order-metrics>div{padding:0 12px}.order-metrics strong{font-size:18px}}</style>
